INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66306466', 66306466, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'POLITEKNIK PERKERETAAPIAN INDONESIA MADIUN', 'Pengadaan Belanja Kegiatan Penyusunan Laporan Tracer Study', 'Barang', 'Pengadaan Langsung', 'Jawa Timur, Madiun (Kota)', 50400000, 'June 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Paket pekerjaan ini berupa pengadaan belanja kegiatan penyusunan laporan tracer study dalam rangka monitoring dan pelaporan penyerapan lulusan diklat transportasi darat di Politeknik Perkeretaapian Indonesia Madiun. Kegiatan ini meliputi pengumpulan data alumni, pelaksanaan diskusi atau pertemuan dengan stakeholder perkeretaapian, serta pengolahan dan penyusunan laporan tracer study sebagai bahan evaluasi terhadap kesesuaian kompetensi lulusan dengan kebutuhan dunia kerja.', 'Spesifikasi pekerjaan meliputi penyediaan kebutuhan kegiatan seperti ATK penunjang kegiatan, kebutuhan peserta, serta dukungan perjalanan dinas untuk pelaksanaan kegiatan monitoring dan penyusunan laporan tracer study. Kegiatan dilaksanakan secara terstruktur sehingga menghasilkan laporan penyerapan lulusan yang akurat dan dapat digunakan sebagai bahan evaluasi dan pengembangan program pendidikan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2690857);
