INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66305284', 66305284, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'POLITEKNIK PERKERETAAPIAN INDONESIA MADIUN', 'Pemeliharaan Gedung Pendidikan', 'Pekerjaan Konstruksi', 'Pengadaan Langsung', 'Jawa Timur, Madiun (Kota)', 1868880000, 'January 2026', 'APBN - BADAN LAYANAN UMUM (F), APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Paket pekerjaan ini berupa pelaksanaan pemeliharaan gedung pendidikan di lingkungan Politeknik Perkeretaapian Indonesia Madiun guna menjaga kondisi bangunan tetap baik, aman, dan layak digunakan untuk kegiatan pendidikan dan pembelajaran. Kegiatan pemeliharaan dilakukan untuk memperbaiki atau merawat bagian bangunan serta fasilitas pendukung yang mengalami kerusakan ringan agar fungsi gedung dapat tetap optimal dalam mendukung kegiatan akademik.', 'Spesifikasi pekerjaan meliputi kegiatan pemeliharaan dan perbaikan ringan pada bagian gedung pendidikan seperti atap, plafon, dinding, lantai, pintu, jendela, serta fasilitas pendukung lainnya sesuai kebutuhan di lapangan. Pekerjaan dilaksanakan dengan menggunakan bahan yang sesuai standar, tenaga kerja yang kompeten, serta memastikan hasil pekerjaan rapi, aman, dan memenuhi fungsi bangunan sebagaimana mestinya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2691990);
