INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66382795', 66382795, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL', 'Pengadaan Sewa Mesin Fotocopy Pada Sekretariat Direktorat Jenderal Kekayaan Intelektual Ta 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 166500000, 'March 2026', 'APBN - PNBP (D)', 1, 1, '10 Bulan', 'Ruang lingkup pekerjaan berupa Penyewaan Mesin Fotocopy yang dilakukan oleh Penyedia untuk pekerjaan jasa sewa mesin fotocopy adalah : 1. Menyediakan 10 (sepuluh) unit mesin fotocopy untuk keperluan Direktorat Jenderal Kekayaan Intelektual Kementerian Hukum dan Hak Asasi Manusia RI; 2. Melakukan pemasangan dan instalasi mesin fotocopy ditempat yang ditentukan, 3. Seluruh mesin fotokopi sudah dalam kondisi siap pakai; 4. Menyampaikan Metode dan Jadwal Pekerjaan selama pelaksanaan pekerjaan sewa mesin fotokopi di Direktorat Jenderal Kekayaan Intelektual Kementerian Hukum dan Hak Asasi Manusia RI. 5. Melaksanakan Pemeliharaan/Perawatan Mesin Fotocopy Yang Terpasang, yang meliputi: 6. pemeliharaan/perawatan secara berkala semua mesin fotokopi minimal sebulan sekali; 7. penanganan atas kerusakan mesin fotokopi, yang meliputi: a. Kecepatan pelayanan teknisi tiba dilokasi maksimal 1 (satu) jam sejak pengaduan kerusakan (respon time); b. kesanggupan melakukan perbaikan dalam tempo maksimal 2 jam sejak laporan gangguan/kerusakan mesin fotocopy diterima; c. Apabila gangguan/kerusakan sebagaimana disebutkan pada point diatas tidak dapat diatasi dalam tempo maksimal 2 (dua) jam sejak laporan gangguan/kerusakan, penyedia harus sanggup menyediakan mesin fotocopy pengganti dengan spesifikasi teknis yang sama maksimal 12 jam sejak laporan gangguan/kerusakan. 8. Ketersediaan Dukungan Teknis, yang meliputi: a. pelayanan 24 jam nonstop setiap hari termasuk hah libur (baik libur Nasional/ Keagamaan) untuk menjamin kelancaran operasional mesin selama 24 jam sekaligus menyediakan layanan staff call center yang bisa dihubungi 24 jam nonstop setiap hari; b. penyedia mencantumkan/menempelkan nomor telepon staff call center yang dapat dihubungi setiap waktu (1 x 24 jam) pada setiap unit mesin fotocopy; c. Mengadakan pelatihan pengoperasian mesin fotokopi kepada pegawai Direktorat Jenderal Kekayaan Intelektual Kementerian Hukum dan Hak Asasi Manusia RI; d. Melaksanakan perawatan rutin atas mesin yang terpasang minimal 1 (satu) bulan sekali; e. Menyediakan tinta untuk masing-masing mesin fotokopi selama masa pelaksanaan pekerjaan sewa mesin fotocopy; f. Surat keterangan ketersediaan suku cadang (spare part) dan bahan pakai mesin fotocopy yang terpasang di Direktorat Jenderal Kekayaan Intelektual Kementerian Hukum dan Hak Asasi Manusia RI dari ATPM/Distributor Resmi yang berkedudukan di Indonesia; g. Menyediakan tenaga customer service minimal 2 (dua) orang yang mampu menjembatani kepentingan Direktorat Jenderal Kekayaan Intelektual Kementerian Hukum dan Hak Asasi Manusia RI dengan Penyedia dengan baik. h. Menyediakan tenaga teknis minimal 1 (satu) orang yang mampu melakukan instalasi, melakukan pemeliharaan, penggantian sparepart maupun perbaikan mesin fotokopi, dengan pengalaman minimal 2 (dua) tahun menjadi teknisi mesin fotocopy yang dibuktikan dengan surat keterangan pengalaman kerja dari pemberi kerja yang menyebutkan lokasi dan periode tugas pada instansi pemerintah yang dilegalisir, tenaga teknis yang dimaksud hams telah mengikuti dan menyelesaikan pelatihan teknis terkait pengoperasian dan pemeliharaan mesin fotocopy, yang diadakan oleh ATPM/Distributor Resmi yang berkedudukan di Indonesia sesuai merk dan type mesin fotokopi yang ditawarkan, yang dibuktikan berupa sertifikat keahlian dari ATPM/Distributor Resmi yang berkedudukan di Indonesia; i. Tenaga teknik maupun customer service dimaksud adalah merupakan karyawan sendiri yang dibuktikan dengan tercantumnya nama karyawan tersebut pada bukti potong PPh Pasal 21 Tahun 2014, dilengkapi CV dan KTP; j. Menyampaikan laporan hasil pekerjaan atas pelayanan jasa sewa mesin fotocopy setiap bulan kepada pemberi tugas.', 'NO Nama Barang dan Spesifikasi Jumlah Jenis/Type Mesin Fotocopy Canon IR5050 10 Unit Fasilitas Digital Copier/Printer/Colour Scanner/DDF Kecepatan Copy Minimal 28 cpm (A4) Resolusi Minimal 1800 x 600 dpi/sesuai pabrikan Ukuran kertas maksimal A3 (297 x 420 mm) Memory standar 2 GB (2048 MB)/sesuai pabrikan Type original Lembaran, Buku dan Obyek 3 dimensi Pengecilan/pembesaran 25-400% Kapasitas Kertas Minimal 1150 lembar Kertas Fotocopy 60-90 g/m2 (tray 1 dan 2), 60-210 g/m2 (multiple bypass tray) Waktu pemanasan Kurang dari 30 detik (main power off) Multi copy 1-9999, penghitungan menurun, bisa diinterupsi Copy bolak balik Standar Sorter Electronic sorting Printing Function Kecepatan mencetak Minimal 28 ppm (A4) Ukuran cetak maksimum A3 (297 x 420 mm) Resolusi Minimal 1800 x 600 dpi/sesuai pabrikan Sistem Operasi Minimal windows 2000 SP3/XP/Vista/Win7/Win8/ Server 2003/Server 2008 MacOS 9.2, OS X (10.2,3,4,5) Penghubung Ethernet IOBase-T/IOOBaseTX/IOOOBaseT Scanning Function Type Full-colour scanner Kecepatan Scan Minimal 70 opm (300 dpi/B&W) Ukuran Original Maksimal A3 (297 x 420 mm) Mode Scan Scan to e-mail, scan to FTP, scan to SMB, dan scan to USB Format File TIFF, PDF, Compact PDF, JPEG Penghubung Ethernet IOBase-T/IOOBaseTX/IOOOBaseT Copy bolak balik Standar Sorter Electronic sorting', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2693215);
